"""A virtual 2-16-16-1 MLP generated by ONE trainable scalar.

No learned embeddings, biases, Mirror codebooks or generator coefficients.
Mirrors are exact invertible pairwise rotations composed with cyclic permutations;
a nonlinear activation is applied BETWEEN the forward and inverse Mirrors.
All fixed constants are analytic functions of position and round index.
This is a differentiable one-dimensional weight manifold, not 337 independent DOF.
"""
import math
import io
import torch
from torch import nn
from torch.nn import functional as F

INPUT, WIDTH, OUTPUT = 2, 16, 1
WEIGHTS = (WIDTH*INPUT + WIDTH + WIDTH*WIDTH + WIDTH + OUTPUT*WIDTH + OUTPUT)


def pairs_rotate(v, angle):
    if v.numel() % 2:
        raise ValueError('Even length required')
    t = v.reshape(-1, 2)
    c, s = torch.cos(angle), torch.sin(angle)
    return torch.stack((c*t[:,0]-s*t[:,1], s*t[:,0]+c*t[:,1]), dim=1).reshape(-1)


def mirror(v, angle, shift, inverse=False):
    # Q := R(angle) roll(shift). Q^-1 = roll(-shift) R(-angle).
    if inverse:
        return torch.roll(pairs_rotate(v, -angle), -shift, 0)
    return pairs_rotate(torch.roll(v, shift, 0), angle)


class VirtualMLP(nn.Module):
    """Sole trainable state `s`; 337 MLP coefficients synthesized on each forward.

    mode='mirror' applies Q^-1 phi(Q z + b) using both rotations and
    permutations; mode='spectral' uses the identical seed without mirror steps;
    mode='linear_view' uses coordinate maps but no nonlinear activation;
    mode='scalar_gain' scales one completely fixed virtual weight vector.
    """
    def __init__(self, mode='mirror', init_s=0.2, rounds=4, dtype=torch.float64):
        super().__init__()
        if mode not in ('mirror','spectral','linear_view','scalar_gain'):
            raise ValueError(mode)
        if rounds < 1:
            raise ValueError('rounds >= 1')
        self.s = nn.Parameter(torch.tensor(float(init_s), dtype=dtype))
        self.mode = mode
        self.rounds = int(rounds)
        self.layer_dims = (INPUT, WIDTH, WIDTH, OUTPUT)

    @staticmethod
    def _trig_seed(s, size, device, dtype):
        # Bounded and smooth in scalar s; role offsets are not stored learned weights.
        i = torch.arange(size, device=device, dtype=dtype)
        phase = (i * 2.399963229728653)  # golden angle, modulo 2pi automatically
        f1 = 1.0 + 0.32*torch.sin(i * 0.017)
        f2 = 1.14 + 0.28*torch.cos(i * 0.029)
        return 0.64*torch.sin(f1*s+phase) + 0.36*torch.cos(f2*s+1.71*phase)

    def virtual_vector(self):
        s = self.s
        n = WEIGHTS + WEIGHTS%2  # pad for two-channel Mirror blocks
        z = self._trig_seed(s, n, s.device, s.dtype)
        if self.mode == 'scalar_gain':
            # One trainable scale applied to a fixed deterministic vector.
            z = self._trig_seed(s.detach()*0.0, n, s.device, s.dtype) * (1.0+0.5*s)
        elif self.mode in ('mirror','linear_view'):
            for j in range(self.rounds):
                a = torch.tensor(0.27 + 0.37*j, device=s.device, dtype=s.dtype) + 0.11*torch.tanh(s)
                shift = (5 + 11*j) % n
                qz = mirror(z, a, shift)
                if self.mode == 'mirror':
                    idx = torch.arange(n, device=s.device, dtype=s.dtype)
                    bias = 0.13*torch.sin(idx * 0.079 + j*1.13)
                    # Activation INSIDE the mirror sandwich: nonlinear coordinate rule.
                    evolved = mirror(torch.tanh(1.15*qz+bias), a, shift, inverse=True)
                    z = 0.73*z + 0.27*evolved
                else:
                    # Linear Q^-1Q is identity: a gauge-null control.
                    z = 0.73*z + 0.27*mirror(qz, a, shift, inverse=True)
        return z[:WEIGHTS]

    def virtual_weights(self):
        z = self.virtual_vector()
        cursor = 0
        matrices=[]
        for in_dim,out_dim in zip(self.layer_dims[:-1],self.layer_dims[1:]):
            count = in_dim*out_dim
            w = z[cursor:cursor+count].reshape(out_dim,in_dim)/math.sqrt(in_dim)
            cursor += count
            b = z[cursor:cursor+out_dim] * 0.18
            cursor += out_dim
            matrices.append((w,b))
        assert cursor == WEIGHTS
        return tuple(matrices)

    def forward(self, x):
        for layer,(w,b) in enumerate(self.virtual_weights()):
            x = F.linear(x,w,b)
            if layer < len(self.layer_dims)-2:
                x = torch.tanh(x)
        return x

    def metadata(self):
        return {'mode':self.mode,'rounds':self.rounds,'layer_dims':list(self.layer_dims),
                'dtype':str(self.s.dtype),'virtual_weights':WEIGHTS,
                'trainable_tensors':len(list(self.parameters())),
                'trainable_scalars':sum(p.numel() for p in self.parameters())}

    def checkpoint_bytes(self):
        payload = {'architecture':self.metadata(), 'state':self.state_dict()}
        f = io.BytesIO()
        torch.save(payload, f)
        return len(f.getvalue())


class DenseMLP(nn.Module):
    """Usual independently trained, structurally identical 2-16-16-1 upper control."""
    def __init__(self):
        super().__init__()
        self.layers = nn.ModuleList((nn.Linear(2,16,dtype=torch.float64),
                                     nn.Linear(16,16,dtype=torch.float64),
                                     nn.Linear(16,1,dtype=torch.float64)))

    def forward(self,x):
        for j,layer in enumerate(self.layers):
            x=layer(x)
            if j<2: x=torch.tanh(x)
        return x

    def checkpoint_bytes(self):
        f=io.BytesIO();torch.save(self.state_dict(),f);return len(f.getvalue())
